sys_script_client.script:
function onSubmit() {
   //Type appropriate comment here, and begin script below
    var baseId = g_form.getValue('base');

    if (!baseId) {
        return true;
    }

    var ga = new GlideAjax('x_1523510_alloca_0.AllocateNowUtils');

    ga.addParam('sysparm_name', 'hasAvailableCapacity');
    ga.addParam('sysparm_base_id', baseId);

    ga.getXMLWait();

    var answer = ga.getAnswer();

    if (answer === 'false') {
		g_form.addErrorMessage(
            'This base has no available capacity.'
        );
        return false;
    }

    return true;
}
